1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.regex.Pattern;
6	
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.MissingFieldsException;
10	import org.springframework.web.bind.annotation.RequestBody;
11	
12	/**
13	 * Rejects a create request that is missing or blank in any required owner field, so an
14	 * incomplete body is a 400 whose {@code errors} array names each offending field. Also
15	 * normalizes the telephone to E.164 form (see {@link TelephoneE164}), republishing the
16	 * normalized value so it is stored and returned as {@code telephone}; a telephone that
17	 * cannot form a valid E.164 number is a 400 too.
18	 * The optional {@code email} is validated only when present: a syntactically invalid
19	 * address is a 400, otherwise it is normalized to lower-case and republished so it is
20	 * stored and returned lower-cased.
21	 * The {@code address} is normalized (see {@link AddressNormalizer}) and republished so it
22	 * is stored and returned in canonical form; an address that is blank after normalization
23	 * is a required-field 400.
24	 * Runs first and republishes the body as a variable for {@link BuildOwner}.
25	 */
26	public class ValidateOwnerFields {
27	
28	    /** Syntactic email check: one '@', non-empty local part, and a dotted domain. */
29	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
30	
31	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
32	            throws MissingFieldsException {
33	        List<String> errors = new ArrayList<>();
34	        if (isBlank(request.getFirstName())) {
35	            errors.add("firstName");
36	        }
37	        if (isBlank(request.getLastName())) {
38	            errors.add("lastName");
39	        }
40	        String address = AddressNormalizer.normalize(request.getAddress());
41	        if (address.isEmpty()) {
42	            errors.add("address");
43	        }
44	        else {
45	            request.setAddress(address);
46	        }
